import heapq

def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    nodes = set(deps)
    for preds in deps.values():
        nodes.update(preds)

    remaining = {n: len(set(deps.get(n, ()))) for n in nodes}
    dependents = {n: [] for n in nodes}
    for x, preds in deps.items():
        for p in set(preds):
            dependents[p].append(x)

    heap = [n for n in nodes if remaining[n] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for m in dependents[n]:
            remaining[m] -= 1
            if remaining[m] == 0:
                heapq.heappush(heap, m)

    if len(order) < len(nodes):
        raise ValueError("cycle detected in dependencies")
    return order
```

