def wildcard_match(s: str, p: str) -> bool:
    if not p:
        return not s
    if all(c == '*' for c in p):
        return True
    if '*' not in p:
        if len(s) != len(p):
            return False
        for a, b in zip(s, p):
            if b != '?' and a != b:
                return False
        return True

    n = len(s)
    m = len(p)

    prev = bytearray(m + 1)
    prev[0] = 1
    for j in range(1, m + 1):
        prev[j] = prev[j - 1] if p[j - 1] == '*' else 0

    for i in range(1, n + 1):
        cur = bytearray(m + 1)
        ch = s[i - 1]
        for j in range(1, m + 1):
            pc = p[j - 1]
            if pc == '*':
                cur[j] = cur[j - 1] or prev[j]
            elif pc == '?' or pc == ch:
                cur[j] = prev[j - 1]
        prev = cur

    return prev[m] == 1
```

