def calc(expr: str) -> float:
    if not isinstance(expr, str):
        raise TypeError("expr must be a string")

    s = expr
    n = len(s)
    i = 0

    def skip_spaces() -> None:
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def parse_expression() -> float:
        nonlocal i
        value = parse_term()
        while True:
            skip_spaces()
            if i < n and s[i] in ('+', '-'):
                op = s[i]
                i += 1
                rhs = parse_term()
                value = value + rhs if op == '+' else value - rhs
            else:
                return value

    def parse_term() -> float:
        nonlocal i
        value = parse_factor()
        while True:
            skip_spaces()
            if i < n and s[i] in ('*', '/'):
                op = s[i]
                i += 1
                rhs = parse_factor()
                value = value * rhs if op == '*' else value / rhs
            else:
                return value

    def parse_factor() -> float:
        nonlocal i
        skip_spaces()
        if i < n and s[i] == '-':
            i += 1
            return -parse_factor()
        if i < n and s[i] == '+':
            i += 1
            return parse_factor()
        return parse_primary()

    def parse_primary() -> float:
        nonlocal i
        skip_spaces()
        if i < n and s[i] == '(':
            i += 1
            value = parse_expression()
            skip_spaces()
            if i >= n or s[i] != ')':
                raise ValueError("expected ')'")
            i += 1
            return value

        start = i
        digit_seen = False
        dot_seen = False
        while i < n and ('0' <= s[i] <= '9' or s[i] == '.'):
            c = s[i]
            if c == '.':
                if dot_seen:
                    raise ValueError("invalid number")
                dot_seen = True
            else:
                digit_seen = True
            i += 1

        if not digit_seen:
            raise ValueError("expected number or '('")
        return float(s[start:i])

    result = parse_expression()
    skip_spaces()
    if i != n:
        raise ValueError("unexpected character")
    return float(result)
