def sliding_median(nums: list[int], k: int) -> list[float]:
    n = len(nums)
    if k <= 0 or n < k:
        return []

    # Coordinate compress
    values = sorted(set(nums))
    m = len(values)
    comp = {v: i + 1 for i, v in enumerate(values)}

    bit = [0] * (m + 1)

    def add(idx, delta):
        while idx <= m:
            bit[idx] += delta
            idx += idx & (-idx)

    def kth(kth):
        # 1-indexed: smallest position j with prefix_sum(j) >= kth
        idx = 0
        bitmask = 1 << m.bit_length()
        while bitmask:
            nxt = idx + bitmask
            if nxt <= m and bit[nxt] < kth:
                kth -= bit[nxt]
                idx = nxt
            bitmask >>= 1
        return idx + 1

    for i in range(k):
        add(comp[nums[i]], 1)

    result = []
    even = k % 2 == 0
    target1 = k // 2 if even else 0  # not used for odd
    for i in range(n - k + 1):
        if even:
            p1 = kth(k // 2)
            p2 = kth(k // 2 + 1)
            result.append((values[p1 - 1] + values[p2 - 1]) / 2.0)
        else:
            p = kth(k // 2 + 1)
            result.append(float(values[p - 1]))
        if i + k < n:
            add(comp[nums[i]], -1)
            add(comp[nums[i + k]], 1)

    return result
```

