def decode_string(s: str) -> str:
    stack = []
    current = []
    count = 0

    for ch in s:
        if '0' <= ch <= '9':
            count = count * 10 + (ord(ch) - ord('0'))
        elif ch == '[':
            stack.append((count, current))
            current = []
            count = 0
        elif ch == ']':
            repeat, parent = stack.pop()
            parent.append(''.join(current) * repeat)
            current = parent
            count = 0
        else:
            current.append(ch)

    return ''.join(current)
